import { Bus } from "../../Engine/Bus";
import { HallEvents } from "../HallEvents";


export class HallViewModel  {

    private _selectedBuildingId: number | null = null;

    private _bus: Bus = null;

    public get selectedBuildingId(): number | null { 
        return this._selectedBuildingId; 
    }

    public selectBuilding(id: number | null): void {
        this._selectedBuildingId = id;
        this._bus.emit(HallEvents.UI_SELECTED_BUILDING_CHANGED, id);
    }

    public requestUpgrade(): void {
        if (this._selectedBuildingId === null) return;
        this._bus.emit(HallEvents.UPGRADE_REQUEST, { buildingId: this._selectedBuildingId });
    }
}


